        sqlc.narg('stock_name'),
        sqlc.narg('stock_code'),
        sqlc.narg('description'),
        sqlc.narg('stock_status'),
        sqlc.narg('sector_id'),
        sqlc.narg('sub_sector_id'),
        sqlc.narg('stock_type_id'),
