        (SELECT s.sub_sector_name FROM sub_sector s WHERE s.id = sqlc.narg('sub_sector_id')),
        sqlc.narg('status'),
        sqlc.arg('actor'),
        sqlc.arg('actor'))
RETURNING uuid;

